function deepClone(value) {
  return JSON.parse(JSON.stringify(value));
}

export function hasEmbeddedSkybox(presetId) {
  const key = Number.parseInt(`${presetId}`, 10);
  return Number.isFinite(key) && Object.hasOwn(EMBEDDED_SKYBOXES, key);
}

export function getEmbeddedSkyboxFaces(presetId) {
  const key = Number.parseInt(`${presetId}`, 10);
  if (!Number.isFinite(key) || !Object.hasOwn(EMBEDDED_SKYBOXES, key)) {
    return null;
  }

  return deepClone(EMBEDDED_SKYBOXES[key]);
}

export function registerEmbeddedSkybox(presetId, faces) {
  const key = Number.parseInt(`${presetId}`, 10);
  if (!Number.isFinite(key) || key < 0) {
    return false;
  }

  if (!faces || typeof faces !== 'object' || Array.isArray(faces)) {
    return false;
  }

  const requiredFaces = ['left', 'right', 'up', 'down', 'front', 'back'];
  for (const face of requiredFaces) {
    if (typeof faces[face] !== 'string' || !faces[face].startsWith('data:image/')) {
      return false;
    }
  }

  EMBEDDED_SKYBOXES[key] = deepClone(faces);
  return true;
}

export function getRandomSkyboxId() {
  const ids = Object.keys(EMBEDDED_SKYBOXES).map(Number);
  if (ids.length === 0) {
    return null;
  }
  const randomId = ids[Math.floor(Math.random() * ids.length)];
  return randomId;
}
export { EMBEDDED_SKYBOXES };
